#include <stdio.h>
#include <stdlib.h>

/* The shape of the tool, in miniature: grow, remember, report, free. */
int main(void)
{
    double *vals = NULL;
    int len = 0, cap = 0;
    double x;
    double demo[] = {18.5, 22.0, 31.0};

    for (int i = 0; i < 3; i++) {          /* the real tool reads with scanf */
        x = demo[i];
        if (len == cap) {
            int new_cap = cap ? cap * 2 : 8;
            double *tmp = realloc(vals, new_cap * sizeof *tmp);
            if (tmp == NULL) break;
            vals = tmp;
            cap = new_cap;
        }
        vals[len++] = x;
    }
    printf("kept %d readings in room for %d\n", len, cap);
    for (int i = 0; i < len; i++)
        if (vals[i] > 30.0) printf("alarm at reading %d: %.1f\n", i + 1, vals[i]);
    free(vals);
    return 0;
}

