typedef struct {
    double *vals;   /* the readings, on the heap */
    int len;
    int cap;
} Readings;

void readings_init(Readings *r)
{
    r->vals = NULL;
    r->len = 0;
    r->cap = 0;
}

int readings_add(Readings *r, double v)
{
    if (r->len == r->cap) {
        int new_cap = r->cap ? r->cap * 2 : 8;
        double *tmp = my_realloc(r->vals, new_cap * sizeof *tmp);
        if (tmp == NULL) return 0;          /* old readings are safe */
        r->vals = tmp;
        r->cap = new_cap;
    }
    r->vals[r->len++] = v;
    return 1;
}

int readings_stats(const Readings *r, double *lo, double *hi, double *avg)
{
    if (r->len == 0) return 0;
    double total = 0;
    *lo = *hi = r->vals[0];
    for (int i = 0; i < r->len; i++) {
        double v = r->vals[i];
        if (v < *lo) *lo = v;
        if (v > *hi) *hi = v;
        total += v;
    }
    *avg = total / r->len;
    return 1;
}

void readings_free(Readings *r)
{
    my_free(r->vals);
    r->vals = NULL;
    r->len = 0;
    r->cap = 0;
}

